[CmdletBinding()] param([string]$ResourceName,[string]$ResourceType,[Parameter(Mandatory)][string]$ResourceGroup,[Parameter(Mandatory)][string]$OutputDirectory,[string]$Subscription)
. (Join-Path $PSScriptRoot 'Common-AzureCollector.ps1');$doc=New-CollectorDocument $ResourceType $ResourceName $ResourceGroup $Subscription
$account=Invoke-AzCommandJson 'storage.account.show' @('storage','account','show','--name',$ResourceName,'--resource-group',$ResourceGroup) $Subscription -Required;Add-CollectorSection $doc 'show' $account
foreach($item in @(@('networkRules','storage','account','network-rule','list'),@('blobService','storage','account','blob-service-properties','show'),@('managementPolicy','storage','account','management-policy','show'))){Add-CollectorSection $doc $item[0] (Invoke-AzCommandJson ('storage.'+$item[0]) (@($item[1..($item.Count-1)])+@('--account-name',$ResourceName,'--resource-group',$ResourceGroup)) $Subscription)}
if($account.data.id){Add-StandardResourceEvidence $doc $account.data.id $Subscription};$file=Join-Path $OutputDirectory ('storage-{0}.json' -f (ConvertTo-CollectorSafeFileName $ResourceName));Save-CollectorDocument $doc $file;[pscustomobject]@{resourceType='storageAccount';name=$ResourceName;outputFile=$file}